/**
 * How to actually fix each failure, per platform.
 *
 * A finding without a fix is a complaint. Every recipe here is concrete enough
 * that a developer can act on it without opening a spec, and platform notes
 * exist because "add an alt attribute" is unhelpful advice to someone whose
 * markup is generated by a Shopify theme they cannot edit directly.
 */

export type PlatformId =
  | 'html'
  | 'shopify'
  | 'wordpress'
  | 'webflow'
  | 'squarespace'
  | 'wix'
  | 'react'
  | 'drupal';

export interface Platform {
  readonly id: PlatformId;
  readonly name: string;
  /** Where a non-developer goes to make the change. */
  readonly editSurface: string;
}

export const PLATFORMS: readonly Platform[] = [
  { id: 'html', name: 'Plain HTML', editSurface: 'the page source' },
  { id: 'shopify', name: 'Shopify', editSurface: 'Online Store → Themes → Edit code, and the product admin' },
  { id: 'wordpress', name: 'WordPress', editSurface: 'the block editor, the Media Library, and your theme templates' },
  { id: 'webflow', name: 'Webflow', editSurface: 'the Designer element settings panel' },
  { id: 'squarespace', name: 'Squarespace', editSurface: 'the page editor and site styles' },
  { id: 'wix', name: 'Wix', editSurface: 'the Editor element settings' },
  { id: 'react', name: 'React and Next.js', editSurface: 'your component source' },
  { id: 'drupal', name: 'Drupal', editSurface: 'Twig templates and field settings' },
] as const;

export const platformById = (id: PlatformId): Platform | undefined =>
  PLATFORMS.find((p) => p.id === id);

export type Effort = 'minutes' | 'hours' | 'days';

export interface Recipe {
  /** axe rule id this fixes. */
  readonly ruleId: string;
  /** Human title, used as the page heading in the fix guides. */
  readonly title: string;
  /** What is actually wrong, in one sentence, without jargon. */
  readonly problem: string;
  /** Who it affects and how. */
  readonly impact: string;
  /** The general fix, platform-independent. */
  readonly fix: readonly string[];
  readonly wrong?: string;
  readonly right?: string;
  readonly effort: Effort;
  /** Mistakes that create a second failure while fixing the first. */
  readonly pitfalls: readonly string[];
  readonly platformNotes: Partial<Record<PlatformId, string>>;
}

