const BY_RULE = new Map(RECIPES.map((r) => [r.ruleId, r]));
export const recipeFor = (ruleId: string): Recipe | undefined => BY_RULE.get(ruleId);
export const hasRecipe = (ruleId: string): boolean => BY_RULE.has(ruleId);

/** Recipes that have a note for the platform, used to build the fix guides. */
export const recipesForPlatform = (id: PlatformId): Recipe[] =>
  RECIPES.filter((r) => r.platformNotes[id] !== undefined);
